input.command:
chcp 65001 | Out-Null
[Console]::OutputEncoding = [System.Text.Encoding]::UTF8
# List Desktop candidate projects
Get-ChildItem "C:\Users\win\Desktop" -Directory -ErrorAction SilentlyContinue | ForEach-Object {
  $p = $_.FullName
  $signals = @()
  if (Test-Path "$p\.git") { $signals += "git" }
  if (Test-Path "$p\AGENTS.md") { $signals += "AGENTS" }
  if (Test-Path "$p\package.json") { $signals += "npm" }
  if (Test-Path "$p\pyproject.toml") { $signals += "py" }
  if (Test-Path "$p\CLAUDE.md") { $signals += "CLAUDE" }
  if ($signals.Count -gt 0) { "$($_.Name) | $p | $($signals -join ',')" }
}
Write-Host "--- codex skills ---"
Get-ChildItem "$env:USERPROFILE\.codex\skills" -Force -ErrorAction SilentlyContinue | Select-Object Name, Mode
Get-ChildItem "$env:USERPROFILE\.codex\.agents" -Force -ErrorAction SilentlyContinue | Select-Object Name, Mode
# skills path in config?
Select-String -Path "$env:USERPROFILE\.codex\config.toml" -Pattern "skill|agents" -SimpleMatch | Select-Object -First 20 Line
